// A block is valid until the next fill over the SAME storage, which
// invalidates every block over it and every row pointer taken from one.
type MinPlainFixBlock struct {
	Base       unsafe.Pointer              // the extent's base, 64-byte aligned
	Projection *MinPlainFixBlockProjection // the projection, at offset 0
	Bytes      int64                       // the extent in use
}

// ---- block fill path: begin ----
// ---- block fill path: end ----
// MinPlainFixBlockOpen is the bool convenience for the handle's typed Open error.
func MinPlainFixBlockOpen(block *MinPlainFixBlock, base unsafe.Pointer, bytes int64) bool {
	return block.Open(base, bytes) == nil
}

// Open reads all prologue and layout words bytewise before the final base
// alignment check. Every refusal names the first failed clause in SPEC §19.2.
func (block *MinPlainFixBlock) Open(base unsafe.Pointer, bytes int64) error {
	*block = MinPlainFixBlock{}
	if _, err := tableBlockOpenHeader(base, bytes, 48); err != nil {
		return err
	}
	used := int64(48)
	padding := (64 - (used % 64)) % 64
	if padding > bytes-used {
		return TableRefuseTruncated
	}
	used += padding
	if uintptr(base)%64 != 0 {
		return TableRefuseUnalignedBase
	}
	block.Base = base
	block.Projection = (*MinPlainFixBlockProjection)(base)
	block.Bytes = used
	return nil
}

// MinPlainFixCounts is gathered before Begin; clamping is the caller's policy.
type MinPlainFixCounts struct {
}

// MinPlainFixBlockStorage owns a maximum-sized extent. Do not copy an initialized storage.
type MinPlainFixBlockStorage struct {
	base       unsafe.Pointer
	allocation []byte
	allocator  TableBlockAllocator
}

func (s *MinPlainFixBlockStorage) Create(a TableBlockAllocator) bool {
	if s == nil || s.allocation != nil || a.Alloc == nil || a.Free == nil {
		return false
	}
	raw := a.Alloc(MinPlainFixBlockMaxBytes + 63)
	if int64(len(raw)) < MinPlainFixBlockMaxBytes+63 {
		if raw != nil {
			a.Free(raw)
		}
		return false
	}
	s.allocation = raw
	s.allocator = a
	s.base = tableBlockAlign64(raw)
	return true
}
func (s *MinPlainFixBlockStorage) Destroy() {
	if s != nil && s.allocation != nil {
		s.allocator.Free(s.allocation)
		*s = MinPlainFixBlockStorage{}
	}
}

// ---- block fill path: begin ----
// MinPlainFixBlockBegin writes only the prologue and triples, never rows or padding.
// Storage and all counts are checked before any byte of the extent changes.
func MinPlainFixBlockBegin(b *MinPlainFixBlock, s *MinPlainFixBlockStorage, c MinPlainFixCounts, refusal *TableBlockRefusal) bool {
	if refusal != nil {
		*refusal = TableBlockRefusal{}
	}
	if b == nil {
		return false
	}
	if s == nil || s.base == nil {
		return false
	}
	p := (*MinPlainFixBlockProjection)(s.base)
	p.Magic = TableBlockMagic
	p.BuildVersion = BuildVersion
	p.ByteOrder = TableBlockByteOrder
	offset := int64(48)
	*b = MinPlainFixBlock{Base: s.base, Projection: p, Bytes: (offset + 63) &^ int64(63)}
	return true
}

func MinPlainFixBlockBytes(b *MinPlainFixBlock) int64 {
	if b == nil || b.Projection == nil {
		return 0
	}
	used := int64(48)
	if b.Projection.FewCount < 2 || b.Projection.FewCount > 4 {
		return -1
	}
	return (used + 63) &^ int64(63)
}

// ---- block fill path: end ----

// Type is this block's descriptors: constant data, so a reflective read costs
// a lookup and not a parse. The row layouts hang off the element column
// rather than taking names of their own, so a walker reaches every record
// through the graph.
func (b *MinPlainFixBlock) Type() *TableBlockInfo { return &tableBlockRecords[7] }
